import{_ as t,o as s,c as a,a2 as n}from"./chunks/framework.CPZ999nZ.js";const u=JSON.parse('{"title":"Testing","description":"","frontmatter":{},"headers":[],"relativePath":"development/testing.md","filePath":"development/testing.md","lastUpdated":1795791670000}'),o={name:"development/testing.md"};function i(r,e,c,d,l,h){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h1><blockquote><p><strong>Note for developing on macOS</strong>: Docker typically runs inside a Linux VM and the socket may not be at the standard <code>/var/run/docker.sock</code> path. The test tooling automatically searches common non-standard socket locations when the standard path is absent. If auto-detection doesn&#39;t find your socket, set the <code>DOCKER_HOST</code> environment variable.</p></blockquote><p>The Saluki testing strategy consists of four main pillars:</p><ol><li>Unit Tests (Rust/cargo)</li><li>Correctness Tests (panoramic)</li><li>Integration Tests (panoramic)</li><li>Performance Tests (SMP)</li></ol><p>Alongside these, we use fuzzing, Loom and Miri for concurrency and memory-model correctness, and Antithesis for fault-injected equivalence testing.</p><h2 id="unit-tests" tabindex="-1">Unit tests <a class="header-anchor" href="#unit-tests" aria-label="Permalink to &quot;Unit tests&quot;">​</a></h2><p>These are found throughout the Rust codebase as you would expect. You can run them with <code>cargo test</code> or you can use <code>make test</code> which will run them with <code>cargo nextest</code> for more parallelization. Platform-specific unit tests should be skipped or compiled-out for platforms they&#39;re incompatible with. For conventions on test naming, table-driven tests, shared fixtures, and assertion density, see <a href="./testing-patterns">Testing patterns</a>.</p><p>CI: <code>.gitlab/test.yml</code>—runs on both Linux (amd64/arm64) and macOS (amd64/arm64).</p><h3 id="fips-unit-tests" tabindex="-1">FIPS unit tests <a class="header-anchor" href="#fips-unit-tests" aria-label="Permalink to &quot;FIPS unit tests&quot;">​</a></h3><p><code>make test-fips</code> runs the unit tests of the crates with FIPS-specific behavior in a FIPS build, which links the AWS-LC FIPS module. Those crates are the ones that have FIPS-only code, or that build TLS configurations and check them for FIPS compliance. Building the FIPS module needs Go and CMake, so <code>make test-all</code> doesn&#39;t include this target. CI runs it on Linux (amd64). Run it when you change TLS configuration or FIPS-specific code.</p><h3 id="tests-that-need-a-docker-daemon" tabindex="-1">Tests that need a Docker daemon <a class="header-anchor" href="#tests-that-need-a-docker-daemon" aria-label="Permalink to &quot;Tests that need a Docker daemon&quot;">​</a></h3><p>Unit tests that create containers are ignored by default, so <code>make test</code> doesn&#39;t need Docker. Run them with <code>make test-container-daemon</code>, which needs a reachable Docker daemon and builds the courier the tests copy into their containers. Their image comes from the internal registry. CI doesn&#39;t run them, so run them by hand when you change the container mechanisms, the container backend or the lifecycle.</p><h3 id="tests-that-need-a-kind-cluster" tabindex="-1">Tests that need a kind cluster <a class="header-anchor" href="#tests-that-need-a-kind-cluster" aria-label="Permalink to &quot;Tests that need a kind cluster&quot;">​</a></h3><p>Unit tests that create pods are ignored too. Run them with <code>make test-kind</code>, which needs <code>kind</code> and <code>kubectl</code> on your <code>PATH</code> and a single-node kind cluster named <code>saluki-correctness</code>, or the one <code>KIND_CLUSTER_NAME</code> names, and builds the courier the tests place on its node. CI doesn&#39;t run them, so run them by hand when you change the pod backend.</p><h3 id="architecture-tests" tabindex="-1">Architecture tests <a class="header-anchor" href="#architecture-tests" aria-label="Permalink to &quot;Architecture tests&quot;">​</a></h3><p>The <code>architecture-tests</code> crate in <code>test/architecture/</code> protects architectural invariants as part of the unit-test suite. Dependency guards check crate relationships; symbol guards restrict names used within selected source directories. Add tests here for other architectural invariants, documenting each beside its test. The crate&#39;s API documentation explains the guards and their limits.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nextest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> architecture-tests</span></span></code></pre></div><p>Failures report a dependency route or source location. Inspect symbol matches before changing code: unrelated names can produce false positives.</p><h2 id="correctness-tests-panoramic" tabindex="-1">Correctness tests (panoramic) <a class="header-anchor" href="#correctness-tests-panoramic" aria-label="Permalink to &quot;Correctness tests (panoramic)&quot;">​</a></h2><p>These tests serve to answer the question: <em>Does ADP produce the same output as the Datadog Agent for a given workload?</em></p><p>To answer this question, a correctness test runs ADP and the Datadog Agent side-by-side in containers and compares their output for a given input. The output comparison is semantic, not a simple byte-by-byte comparison, thus heuristics are used to assert correctness.</p><p><strong>Terminology Note:</strong> Correctness tests <em><strong>are integration tests</strong></em> in the sense that they run the entire system. However, in our repository, <em>integration tests</em> refer to a specific set of smoke tests <a href="#integration-tests-panoramic">below</a>.</p><p>Correctness test cases are specified by YAML configuration files found in <code>test/correctness/cases</code>. For the case format, the steps, and how to read results, see <a href="./panoramic">Panoramic cases</a>.</p><h3 id="binaries-and-program-flow" tabindex="-1">Binaries and program flow <a class="header-anchor" href="#binaries-and-program-flow" aria-label="Permalink to &quot;Binaries and program flow&quot;">​</a></h3><p>All binaries live under <code>bin/correctness/</code>:</p><table tabindex="0"><thead><tr><th>Binary</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>panoramic</strong></td><td>Test runner for the correctness and integration tests.</td></tr><tr><td><strong>millstone</strong></td><td>Deterministic load generator.</td></tr><tr><td><strong><code>otlp-fixtures</code></strong></td><td>Builds the static OTLP payloads of some correctness cases.</td></tr><tr><td><strong>datadog-intake</strong></td><td>Mock Datadog API: receives test output</td></tr><tr><td><strong>airlock</strong></td><td>Library for running containers in isolated groups.</td></tr><tr><td><strong>courier</strong></td><td>Static probe, send, HTTP and file-follow tool that panoramic runs inside containers.</td></tr></tbody></table><p>Test case configs live in <code>test/correctness/cases/</code> (for example, <code>test/correctness/cases/dsd-plain/config.yaml</code>).</p><h3 id="program-flow" tabindex="-1">Program flow <a class="header-anchor" href="#program-flow" aria-label="Permalink to &quot;Program flow&quot;">​</a></h3><p><strong>panoramic</strong> is the entry-point for running a test. When given a correctness test config, it orchestrates the containers using the <code>airlock</code> library (which talks to containerd via gRPC) and asserts the correctness of the output. It:</p><ul><li>reads the test configuration files</li><li>starts two sets of containers <ul><li><code>millstone</code> -&gt; ADP -&gt; <code>datadog-intake</code></li><li><code>millstone</code> -&gt; Datadog Agent -&gt; <code>datadog-intake</code></li></ul></li><li>takes the output from <code>datadog-intake</code> and asserts that ADP and Datadog Agent behavior were equivalent</li></ul><h3 id="running" tabindex="-1">Running <a class="header-anchor" href="#running" aria-label="Permalink to &quot;Running&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run all correctness tests:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-correctness</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run a single test case:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-correctness-case</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CASE=dsd-plain</span></span></code></pre></div><p>The <code>test-correctness</code> target handles building all of the necessary prerequisites -- <code>millstone</code>, <code>datadog-intake</code>, <code>panoramic</code>, the bundled Agent/ADP image, and so on -- before running the test cases.</p><p>Correctness tests are run in the <code>e2e</code> stage in CI (<code>.gitlab/e2e.yml</code>).</p><h3 id="otlp-receiver-endpoints" tabindex="-1">OTLP receiver endpoints <a class="header-anchor" href="#otlp-receiver-endpoints" aria-label="Permalink to &quot;OTLP receiver endpoints&quot;">​</a></h3><p>A correctness case that sends OTLP to ADP and to the Agent leaves <code>otlp_config.receiver.protocols.*.endpoint</code> unset in <code>datadog.yaml</code>. The <code>adp</code> participant&#39;s environment sets <code>DD_OTLP_CONFIG_RECEIVER_PROTOCOLS_{GRPC,HTTP}_ENDPOINT</code>, and ADP and the Agent in its container read the same value. The <code>agent</code> participant takes the harness default, which setting the key in <code>datadog.yaml</code> would withdraw.</p><h3 id="static-fixtures" tabindex="-1">Static fixtures <a class="header-anchor" href="#static-fixtures" aria-label="Permalink to &quot;Static fixtures&quot;">​</a></h3><p>Some cases send a fixed request through a <code>static_base64</code> payload in a sender config, such as a correctness case&#39;s <code>millstone.yaml</code>. <code>bin/correctness/otlp-fixtures</code> builds that request, with a module for each OTLP signal that has static payloads: edit the fixture there, then run <code>make generate-correctness-fixtures</code> to rewrite the payloads. Don&#39;t edit the payloads by hand. To add a fixture, create the sender config with a <code>static_base64: &quot;&quot;</code> placeholder, then add a table entry in <code>main.rs</code> with the config&#39;s path from the repository root. The <code>check-correctness-fixtures</code> CI job runs the same target and fails if it changes any committed payload.</p><p>Name every sender config that <code>otlp-fixtures</code> writes <code>millstone*.yaml</code>, such as <code>millstone.yaml</code> or <code>millstone-traces-grpc.yaml</code>. Millstone&#39;s <code>every_test_case_config_parses</code> test only checks files with that name, so a differently named config skips the parse and validation check. <code>otlp-fixtures</code> refuses a target with another name. The trace builder in <code>traces.rs</code> takes a seed for the trace and span IDs: give each fixture that can reach the same destination its own seed, such as one per protocol.</p><h2 id="integration-tests-panoramic" tabindex="-1">Integration tests (panoramic) <a class="header-anchor" href="#integration-tests-panoramic" aria-label="Permalink to &quot;Integration tests (panoramic)&quot;">​</a></h2><p>Integration tests run ADP, with the Datadog Agent where a case needs it, and assert high-level invariants: process stability, expected log output, port availability, exit behavior, and the metrics that reach a mock intake. Each case runs on the OSes it declares: in Linux and Windows containers, and as host processes on macOS. They catch regressions from enabling new features or settings that cause crashes or early exits. They don&#39;t compare ADP&#39;s output with the Datadog Agent&#39;s. This type of test is often known as a &quot;smoke test.&quot; For tests that compare the two, see <a href="#correctness-tests-panoramic">correctness tests</a> above.</p><p>Test cases live in <code>test/integration/cases/</code>, one directory for each case, and the runner is <strong>panoramic</strong> (<code>bin/correctness/panoramic/</code>). Panoramic runs integration and correctness cases the same way: the directory says what a case is for. See <a href="./panoramic#the-two-suites">The two suites</a>. <a href="./panoramic">Panoramic cases</a> explains how to write a case, run one, and read its results.</p><h3 id="running-1" tabindex="-1">Running <a class="header-anchor" href="#running-1" aria-label="Permalink to &quot;Running&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-integration</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # build images + run all</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-integration-quick</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # skip image builds</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list-integration-tests</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # list available tests</span></span></code></pre></div><p>Panoramic moves every port the Datadog Agent and ADP bind off its default value, so tests don&#39;t collide with an Agent already running on the host. The defaults live in <code>DEFAULT_ENV</code> in <code>bin/correctness/panoramic/src/participants/datadog_agent.rs</code>. A port that a test binds <strong>MUST</strong> be below 49152. On macOS, tests run as host processes, and ports from 49152 up are handed out as source ports for outbound connections. macOS refuses to bind a port that another user&#39;s process holds, so a listener in that range fails intermittently.</p><p>CI: <code>.gitlab/e2e.yml</code>—same file as correctness, <code>e2e</code> stage. The Windows job is in <code>.gitlab/windows.yml</code>.</p><p>The <code>panoramic</code> skill walks LLM agents through choosing and running a suite non-interactively.</p><h2 id="benchmark-tests-single-machine-performance-smp" tabindex="-1">Benchmark tests: Single Machine Performance (SMP) <a class="header-anchor" href="#benchmark-tests-single-machine-performance-smp" aria-label="Permalink to &quot;Benchmark tests: Single Machine Performance (SMP)&quot;">​</a></h2><p>SMP is a system that runs on internal, dedicated infrastructure to check the Agent for performance regressions. It runs experiments across multiple replicates with statistical analysis and posts reports to PRs. Maps to the <code>benchmark</code> stage in GitLab CI (<code>.gitlab/benchmark.yml</code>).</p><p>Each experiment pairs a <strong>target</strong> (ADP container) with <strong>Lading</strong> (deterministic load generator). Lading sends payloads (DogStatsD, OTLP, logs, etc.) at configured rates using seeded generators for reproducibility. SMP measures CPU, memory, throughput—not output correctness.</p><h3 id="experiments" tabindex="-1">Experiments <a class="header-anchor" href="#experiments" aria-label="Permalink to &quot;Experiments&quot;">​</a></h3><p>Defined in <code>test/smp/regression/adp/experiments.yaml</code>. Run <code>make generate-smp-experiments</code> to generate per-case configs into two suites: <code>test/smp/regression/adp/quality-gates/</code> (experiments with <code>checks:</code> bounds) and <code>test/smp/regression/adp/full/</code> (all experiments). Each case gets an <code>experiment.yaml</code> (target config) and <code>lading/lading.yaml</code> (load config). See <code>test/smp/README.md</code> for the suite model.</p><p>PRs gate only on the quality-gates suite, comparing the branch against the merge-base of main—&quot;has your change regressed or improved against the bounds?&quot; The full suite runs nightly on <code>main</code> (date-anchored against the previous nightly, reported to Slack) and on-demand as a manual job on a PR; it is for long-term trend analysis and does not gate.</p><p>You can run experiments locally with <code>smp local-run</code> to debug experiment configs without waiting for CI (single replicate, no statistical analysis). This is mainly useful when iterating on a new or broken experiment—for normal development, lean on CI.</p><h2 id="reviewing-test-changes" tabindex="-1">Reviewing test changes <a class="header-anchor" href="#reviewing-test-changes" aria-label="Permalink to &quot;Reviewing test changes&quot;">​</a></h2><p>Reviewers check test changes against two checklists: one for the test tools, and one for the test cases.</p><h3 id="correctness-tooling-review-checklist" tabindex="-1">Correctness tooling review checklist <a class="header-anchor" href="#correctness-tooling-review-checklist" aria-label="Permalink to &quot;Correctness tooling review checklist&quot;">​</a></h3><p>Reviewers check changes to the tools under <code>bin/correctness/</code> against these rules:</p><p>Apply these rules to files under <code>bin/correctness/</code>: <code>panoramic</code>, <code>millstone</code>, <code>airlock</code>, <code>stele</code>, <code>datadog-intake</code>, and <code>otlp-fixtures</code>. Look first for bugs that hang a run, crash it, leave processes or containers behind, or let a case pass when ADP is wrong.</p><ul><li>Each wait, probe, and exec has a deadline, and each read has a deadline or an idle timeout. A target that stops responding fails the case, and doesn&#39;t hang the job.</li><li>An analysis compares only output that the case controls. It removes the targets&#39; own telemetry, as <code>is_internal_telemetry</code> does in the metrics analysis, because that telemetry depends on timing and on the container.</li><li>Don&#39;t ask for edge cases that no current case can produce. An analysis that is too strict fails a case, so it doesn&#39;t hide a regression. Flag analysis logic that can let a case pass when ADP is wrong, such as a filter or a tolerance that also matches real output.</li><li>Make sure that a regression in the testing harness and libraries doesn&#39;t leave a formerly asserted invariant unchecked.</li></ul><h3 id="test-case-review-checklist" tabindex="-1">Test case review checklist <a class="header-anchor" href="#test-case-review-checklist" aria-label="Permalink to &quot;Test case review checklist&quot;">​</a></h3><p>Reviewers check changes to the test cases under <code>test/</code> against these rules:</p><p>Apply these rules to files under <code>test/</code>: correctness cases, integration cases, and SMP experiments.</p><ul><li>A correctness case must fail when ADP is wrong.</li><li>The Core Agent and ADP can both run some pipelines, such as DogStatsD and OTLP. If ADP doesn&#39;t receive the traffic, the Core Agent handles it, and the case compares the Agent with itself. When a case turns on such a pipeline in ADP, ask what shows that ADP received the traffic. Don&#39;t ask when the case or the description already shows it.</li><li>With <code>DD_DATA_PLANE_STANDALONE_MODE</code> set to <code>&quot;true&quot;</code>, ADP uses only its local configuration and doesn&#39;t register with the Core Agent. The value is <code>&quot;false&quot;</code> or unset in connected mode, which is the production mode. Ask for a connected-mode case when a change affects how settings reach ADP. Examples are changes to the configuration stream, registration, and environment translation.</li><li>The <code>baseline</code> and <code>comparison</code> targets differ only in the setting under test and in the settings that turn on ADP. Settings that only ADP reads can also differ, such as <code>DD_AGGREGATE_CONTEXT_LIMIT</code> and <code>ADP_DD_</code> variables. Flag a setting that the Datadog Agent also reads and that only one side sets, when no comment explains it.</li><li>Flag a setting in a case or an SMP experiment that ADP no longer reads, such as a removed or renamed key. ADP ignores it without an error, so the case no longer tests it. For SMP, comment on <code>test/smp/regression/adp/experiments.yaml</code>, not on the generated <code>experiment.yaml</code> files.</li></ul><h2 id="fuzzing" tabindex="-1">Fuzzing <a class="header-anchor" href="#fuzzing" aria-label="Permalink to &quot;Fuzzing&quot;">​</a></h2><p>We aren&#39;t doing a lot with fuzzing right now, but what we&#39;ve uses <code>cargo-fuzz</code> and operates at the function-level. More fuzzing coverage will likely come in the future.</p><h2 id="loom-and-miri-testing" tabindex="-1">Loom and Miri testing <a class="header-anchor" href="#loom-and-miri-testing" aria-label="Permalink to &quot;Loom and Miri testing&quot;">​</a></h2><p>Loom and Miri target concurrency and memory-model correctness rather than business logic. <strong>Loom</strong> exhaustively explores how concurrent operations can interleave, to catch ordering bugs that are hard to hit through normal test runs. Run it with <code>make test-loom</code>. <strong>Miri</strong> runs tests under an interpreter that catches undefined behavior—data races, use-after-free, invalid memory access—that a normal test run wouldn&#39;t detect. Run it with <code>make test-miri</code>.</p><h2 id="antithesis" tabindex="-1">Antithesis <a class="header-anchor" href="#antithesis" aria-label="Permalink to &quot;Antithesis&quot;">​</a></h2><p><a href="https://antithesis.com/" target="_blank" rel="noreferrer">Antithesis</a> runs ADP under deterministic simulation with injected faults. Our focus is on establishing that ADP and the Datadog Agent&#39;s DogStatsD behave equivalently: if ADP replaces the Agent&#39;s DogStatsD server, users shouldn&#39;t notice shifts in their telemetry. Better operational behavior is an acceptable deviation.</p><p>This is separate from the panoramic correctness tests, which compare outputs for fixed workloads without fault injection. The harness and scenarios live under <code>test/antithesis/</code>, and <code>test/antithesis/AGENTS.md</code> describes how agents drive runs there.</p><h2 id="directory-index" tabindex="-1">Directory index <a class="header-anchor" href="#directory-index" aria-label="Permalink to &quot;Directory index&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.gitlab/</span></span>
<span class="line"><span>├── test.yml               unit tests</span></span>
<span class="line"><span>├── e2e.yml                correctness + integration</span></span>
<span class="line"><span>├── benchmark.yml          SMP benchmarks</span></span>
<span class="line"><span>└── fuzz.yml               fuzz testing</span></span>
<span class="line"><span></span></span>
<span class="line"><span># custom test tooling</span></span>
<span class="line"><span>bin/correctness/</span></span>
<span class="line"><span>├── panoramic/             : test runner (correctness + integration)</span></span>
<span class="line"><span>├── millstone/             : load generator</span></span>
<span class="line"><span>├── otlp-fixtures/         : static OTLP payload builder</span></span>
<span class="line"><span>├── datadog-intake/        : mock Datadog API</span></span>
<span class="line"><span>├── airlock/               : container isolation lib</span></span>
<span class="line"><span>├── courier/               : in-container probe and send tool</span></span>
<span class="line"><span>└── stele/                 : telemetry data types</span></span>
<span class="line"><span></span></span>
<span class="line"><span># actual test cases</span></span>
<span class="line"><span>test/</span></span>
<span class="line"><span>├── correctness/           : correctness test configs</span></span>
<span class="line"><span>├── antithesis/            : antithesis harness and scenarios</span></span>
<span class="line"><span>├── integration/           : integration test configs</span></span>
<span class="line"><span>└── smp/                   : smp experiments</span></span></code></pre></div>`,73)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
